import { splitLines } from './parse.js'

const DIGEST = /^[0-9a-f]{8}$/

/** One refusal of a snapshot line, carrying the 1-based line it was read from. */
export class SnapshotError extends Error {
  /**
   * @param {number} line - the 1-based snapshot line.
   * @param {string} message - the message the specification words, without any prefix.
   */
  constructor(line, message) {
    super(message)
    this.name = 'SnapshotError'
    this.line = line
  }
}

/**
 * Parse a snapshot's text into the digest it records for each path. A line is trimmed
 * first; an empty one and one that starts with `#` are ignored; the rest is split on
 * runs of whitespace into exactly a path and its digest.
 * @param {string} text - the whole snapshot.
 * @returns {Map<string, string>} the digest by path, in recorded order.
 */
export function parseSnapshot(text) {
  const recorded = new Map()
  for (const [index, raw] of splitLines(text).entries()) {
    const line = index + 1
    const value = raw.trim()
